effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    float a = radians(angle);
    mat2 rot = mat2(cos(a),-sin(a),sin(a),cos(a));
    vec2 px = (acScreenNorm*acScreenSize);
    vec2 grid = rot*px/size;
    vec2 cell = fract(grid)-0.5;
    float d = length(cell);
    if(colored){
        vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
        float dotv = step(d, sqrt(dot(c,vec3(0.333)))*0.8);
        gl_FragColor = vec4(c*dotv,1.0)*src.a;
    } else {
        float lum = dot(src.rgb, vec3(0.299,0.587,0.114));
        float r = sqrt(lum)*0.78;
        float m = smoothstep(r+0.05, r-0.05, d);
        vec3 col = mix(paper.rgb, ink.rgb, m);
        gl_FragColor = vec4(col,1.0)*src.a;
    }
}
